package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_siblingElements_TriageGen1Test {

    @Test
    public void testSiblingElementsWithMultipleChildren() {
        String html = "<div><p>One</p><p>Two</p><p>Three</p></div>";
        Document doc = Parser.parse(html);
        Element parent = doc.child(0);
        Element firstChild = parent.child(0);

        Elements siblings = firstChild.siblingElements();

        Assert.assertEquals("siblingElements should return all children of the parent", 3, siblings.size());
        Assert.assertEquals("First sibling should be the first child of parent", "One", siblings.get(0).text());
        Assert.assertEquals("Second sibling should be the second child of parent", "Two", siblings.get(1).text());
        Assert.assertEquals("Third sibling should be the third child of parent", "Three", siblings.get(2).text());
    }

    @Test
    public void testSiblingElementsWithSingleChild() {
        String html = "<div><p>Only Child</p></div>";
        Document doc = Parser.parse(html);
        Element parent = doc.child(0);
        Element child = parent.child(0);

        Elements siblings = child.siblingElements();

        Assert.assertEquals("siblingElements should return 1 element when parent has only one child", 1, siblings.size());
        Assert.assertEquals("The sibling should be the child itself", "Only Child", siblings.get(0).text());
    }

    @Test
    public void testSiblingElementsWithNoChildren() {
        // This case is technically impossible via standard DOM traversal if the element exists,
        // but we test the logic: if an element is orphaned (no parent), parent() returns null.
        // However, per Jsoup implementation, an Element usually has a parent or is the Document.

        String html = "<div></div>";
        Document doc = Parser.parse(html);
        Element emptyDiv = doc.child(0);
        // We can't easily get a child that doesn't exist to call siblingElements on, 
        // but we can test an element that is the parent itself.

        // Testing a node that has no children (though siblingElements is called on a child)
        // If we create a manual element without a parent:
        Element orphan = new Element(org.jsoup.parser.Tag.valueOf("div"), "");

        try {
            orphan.siblingElements();
            Assert.fail("Expected NullPointerException because parent() is null");
        } catch (NullPointerException e) {
            // Expected behavior: parent() returns null, calling .children() on null throws NPE
        }
    }

    @Test
    public void testSiblingElementsWithComplexStructure() {
        String html = "<ul><li>A</li><li>B</li><li>C</li></ul>";
        Document doc = Parser.parse(html);
        Element liB = doc.select("li").get(1);

        Elements siblings = liB.siblingElements();

        Assert.assertEquals(3, siblings.size());
        List<String> texts = siblings.stream().map(Element::text).toList();
        Assert.assertTrue(texts.contains("A"));
        Assert.assertTrue(texts.contains("B"));
        Assert.assertTrue(texts.contains("C"));
    }
}
